class ArrayAccessor {
    int data[1] = { 100 };

public:
    // Non-const overload: returns modifiable reference
    int& operator[](size_t i) {
        return data[i];
    }

    // Const overload: returns read-only reference
    // Used when the object itself is const
    const int& operator[](size_t i) const {
        return data[i];
    }
};

// Example usage contrast:
// ArrayAccessor a;
// const ArrayAccessor c_a;
// a[0] = 5;      // Uses non-const version
// int x = c_a[0]; // Uses const version
